## 2. 限流算法

### 2.1 令牌桶算法

```go
// ratelimit/token_bucket.go

type TokenBucket struct {
    mu          sync.Mutex
    tokens      float64
    maxTokens   float64
    refillRate  float64 // 每秒补充的令牌数
    lastRefill  time.Time
}

func NewTokenBucket(maxTokens, refillRate float64) *TokenBucket {
    return &TokenBucket{
        tokens:     maxTokens,
        maxTokens:  maxTokens,
        refillRate: refillRate,
        lastRefill: time.Now(),
    }
}

func (tb *TokenBucket) Allow() bool {
    tb.mu.Lock()
    defer tb.mu.Unlock()

    now := time.Now()
    elapsed := now.Sub(tb.lastRefill).Seconds()
    tb.tokens += elapsed * tb.refillRate
    if tb.tokens > tb.maxTokens {
        tb.tokens = tb.maxTokens
    }
    tb.lastRefill = now

    if tb.tokens >= 1 {
        tb.tokens -= 1
        return true
    }
    return false
}

func (tb *TokenBucket) TryAcquire(n float64) bool {
    tb.mu.Lock()
    defer tb.mu.Unlock()

    now := time.Now()
    elapsed := now.Sub(tb.lastRefill).Seconds()
    tb.tokens += elapsed * tb.refillRate
    if tb.tokens > tb.maxTokens {
        tb.tokens = tb.maxTokens
    }
    tb.lastRefill = now

    if tb.tokens >= n {
        tb.tokens -= n
        return true
    }
    return false
}
```

### 2.2 滑动窗口算法

```go
// ratelimit/sliding_window.go

type SlidingWindow struct {
    mu         sync.Mutex
    windows    []WindowEntry
    windowSize time.Duration
    maxRequests int
}

type WindowEntry struct {
    start time.Time
    count int
}

func NewSlidingWindow(windowSize time.Duration, maxRequests int) *SlidingWindow {
    return &SlidingWindow{
        windows:     make([]WindowEntry, 0),
        windowSize:  windowSize,
        maxRequests: maxRequests,
    }
}

func (sw *SlidingWindow) Allow() bool {
    sw.mu.Lock()
    defer sw.mu.Unlock()

    now := time.Now()
    cutoff := now.Add(-sw.windowSize)

    // 清理过期窗口
    validWindows := make([]WindowEntry, 0)
    totalRequests := 0
    for _, w := range sw.windows {
        if w.start.After(cutoff) {
            validWindows = append(validWindows, w)
            totalRequests += w.count
        }
    }
    sw.windows = validWindows

    // 检查是否超过限制
    if totalRequests >= sw.maxRequests {
        return false
    }

    // 添加新请求
    sw.windows = append(sw.windows, WindowEntry{
        start: now,
        count: 1,
    })

    return true
}
```

### 2.3漏桶算法

```go
// ratelimit/leaky_bucket.go

type LeakyBucket struct {
    mu         sync.Mutex
    water      float64
    capacity   float64
    leakRate   float64 // 每秒漏出的水量
    lastLeak   time.Time
}

func NewLeakyBucket(capacity, leakRate float64) *LeakyBucket {
    return &LeakyBucket{
        capacity: capacity,
        leakRate: leakRate,
        lastLeak: time.Now(),
    }
}

func (lb *LeakyBucket) Allow() bool {
    lb.mu.Lock()
    defer lb.mu.Unlock()

    now := time.Now()
    elapsed := now.Sub(lb.lastLeak).Seconds()
    lb.water -= elapsed * lb.leakRate
    if lb.water < 0 {
        lb.water = 0
    }
    lb.lastLeak = now

    if lb.water + 1 <= lb.capacity {
        lb.water += 1
        return true
    }
    return false
}
