## 4. 熔断降级

### 4.1 熔断器实现

```go
// circuit_breaker/circuit.go

type State int

const (
    Closed State = iota
    Open
    HalfOpen
)

type CircuitBreaker struct {
    mu            sync.Mutex
    state         State
    failureCount  int
    successCount  int
    threshold     int
    timeout       time.Duration
    lastFailure   time.Time
    halfOpenMax   int
}

func NewCircuitBreaker(threshold, halfOpenMax int, timeout time.Duration) *CircuitBreaker {
    return &CircuitBreaker{
        state:       Closed,
        threshold:   threshold,
        timeout:     timeout,
        halfOpenMax: halfOpenMax,
    }
}

func (cb *CircuitBreaker) Execute(fn func() error) error {
    cb.mu.Lock()
    state := cb.state
    cb.mu.Unlock()

    switch state {
    case Closed:
        return cb.executeInClosed(fn)
    case Open:
        return cb.executeInOpen(fn)
    case HalfOpen:
        return cb.executeInHalfOpen(fn)
    }
    return nil
}

func (cb *CircuitBreaker) executeInClosed(fn func() error) error {
    err := fn()

    cb.mu.Lock()
    defer cb.mu.Unlock()

    if err != nil {
        cb.failureCount++
        if cb.failureCount >= cb.threshold {
            cb.state = Open
            cb.lastFailure = time.Now()
        }
    } else {
        cb.failureCount = 0
    }

    return err
}

func (cb *CircuitBreaker) executeInOpen(fn func() error) error {
    cb.mu.Lock()
    defer cb.mu.Unlock()

    if time.Since(cb.lastFailure) > cb.timeout {
        cb.state = HalfOpen
        cb.successCount = 0
        return cb.executeInHalfOpen(fn)
    }

    return fmt.Errorf("circuit breaker is open")
}

func (cb *CircuitBreaker) executeInHalfOpen(fn func() error) error {
    err := fn()

    cb.mu.Lock()
    defer cb.mu.Unlock()

    if err != nil {
        cb.state = Open
        cb.lastFailure = time.Now()
    } else {
        cb.successCount++
        if cb.successCount >= cb.halfOpenMax {
            cb.state = Closed
            cb.failureCount = 0
        }
    }

    return err
}
```

